create table public.gb_invoices (id uuid primary key default gen_random_uuid(), number bigint generated always as identity unique, owner_id uuid not null references auth.users(id), client text not null, email text not null, address text not null default '', issued date not null, due date not null, items jsonb not null, tax_cents bigint not null default 0, total_cents bigint not null, notes text not null default '', status text not null default 'draft' check(status in ('draft','sent','paid')), created_at timestamptz not null default now(), sent_at timestamptz, email_id text); alter table public.gb_invoices enable row level security; revoke all on public.gb_invoices from anon, authenticated; grant select,insert,update on public.gb_invoices to service_role; grant usage,select on sequence public.gb_invoices_number_seq to service_role;